1	use anyhow::{Context, Result};
2	use chrono::{DateTime, Utc};
3	use crossterm::{
4	    cursor,
5	    event::{self, Event, KeyCode},
6	    execute,
7	    terminal::{self, ClearType, EnterAlternateScreen, LeaveAlternateScreen},
8	};
9	use std::io::{self, IsTerminal, Write};
10	
11	// ── Hit types ─────────────────────────────────────────────────────────────────
12	
13	#[derive(Clone)]
14	enum HitKind {
15	    Log,
16	    Checkpoint,
17	    Session,
18	    Repo,
19	    RepoHeader, // non-selectable separator injected between repo groups
20	}
21	
22	impl HitKind {
23	    fn label(&self) -> &'static str {
24	        match self {
25	            HitKind::Log        => "log",
26	            HitKind::Checkpoint => "cp",
27	            HitKind::Session    => "ses",
28	            HitKind::Repo       => "rep",
29	            HitKind::RepoHeader => "",
30	        }
31	    }
32	}
33	
34	struct SearchHit {
35	    kind: HitKind,
36	    title: String,
37	    dir: String,
38	    excerpt_lines: Vec<String>, // context lines: prev turn, matched turn, next turn
39	    match_line_idx: usize,      // which index in excerpt_lines is the actual match
40	    session_id: Option<String>,
41	    repo_dir: Option<String>,
42	    turn_id: Option<String>,       // JSONL message uuid — used for precise navigation
43	    hit_ts: Option<String>,        // timestamp of the matched turn (for display)
44	    hit_off: Option<u64>,          // byte offset in the JSONL of the matched line
45	    checkpoint_id: Option<String>, // for HitKind::Checkpoint — navigate to the specific checkpoint card
46	    branch: String,
47	    // enriched from gossamer DB after search
48	    agent: String,
49	    backed_up: bool,
50	    updated_at: String,
51	    remote: String,
52	    repo_name: String,
53	    author: String, // session author (first-checkpoint commit author), name > email > os_user
54	}
55	
56	// Groups hits from the same session together under one header row.
57	struct Group {
58	    title: String,
59	    dir: String,
60	    branch: String,
61	    agent: String,
62	    backed_up: bool,
63	    updated_at: String,
64	    remote: String,
65	    repo_name: String,
66	    session_id: Option<String>,
67	    repo_dir: Option<String>,
68	    kind: HitKind,
69	    rows: Vec<GroupRow>,
70	    author: String,
71	}
72	
73	struct GroupRow {
74	    hit_ts: Option<String>,
75	    hit_off: Option<u64>,
76	    turn_id: Option<String>,
77	    checkpoint_id: Option<String>,
78	    lines: Vec<String>,
79	    /// Index into `lines` of the actually-matched chunk (others are context).
80	    match_line_idx: usize,
81	    is_checkpoint: bool,
82	}
83	
84	// ── Entry point ───────────────────────────────────────────────────────────────
85	
86	/// Returns `Ok(true)` if the user pressed `q` (or Ctrl+C) anywhere within the
87	/// search TUI or any nested viewer — parent TUI loops should propagate this
88	/// as a full-app exit. `Ok(false)` means a normal back-out (Esc).
89	pub fn run(query: &str, top_k: usize, json: bool) -> Result<bool> {
90	    let assets = crate::config::resolve_warp_assets()
91	        .ok_or_else(|| anyhow::anyhow!(
92	            "Witchcraft assets not configured.\nRun: gossamer config <path-to-witchcraft-assets>"
93	        ))?;
94	
95	    let db_path = dirs::home_dir()
96	        .ok_or_else(|| anyhow::anyhow!("cannot determine home directory"))?
97	        .join(".gossamer/search.db");
98	
99	    let db = witchcraft::DB::new_reader(db_path)
100	        .map_err(|e| anyhow::anyhow!("failed to open search DB: {e}"))?;
101	    let device = witchcraft::make_device();
102	    let embedder = witchcraft::Embedder::new(&device, &assets)
103	        .context("failed to load embedder")?;
104	    let mut cache = witchcraft::EmbeddingsCache::new(1);
105	
106	    const FLOOR:         f32 = 0.20;
107	    const LOG_THRESHOLD: f32 = 0.40;
108	    const SES_THRESHOLD: f32 = 0.25;
109	    const REP_THRESHOLD: f32 = 0.25;
110	
111	    let t0 = std::time::Instant::now();
112	    let raw = witchcraft::search(&db, &embedder, &mut cache, query, FLOOR, top_k * 4, true, None)?;
113	    let ms = t0.elapsed().as_millis();
114	
115	    // Collect all above-threshold witchcraft hits (up to top_k*4), then cap
116	    // at 2 per session so one long session can't crowd out the rest.
117	    const MAX_HITS_PER_SESSION: usize = 2;
118	    let mut session_hit_counts: std::collections::HashMap<String, usize> = std::collections::HashMap::new();
119	    let mut hits: Vec<SearchHit> = raw
120	        .iter()
121	        .filter_map(|(score, meta, bodies, sub_idx, _date)| {
122	            let hit = parse_hit(meta, bodies, *sub_idx as u32);
123	            let threshold = match hit.kind {
124	                HitKind::Log | HitKind::Checkpoint => LOG_THRESHOLD,
125	                HitKind::Session                   => SES_THRESHOLD,
126	                HitKind::Repo | HitKind::RepoHeader => REP_THRESHOLD,
127	            };
128	            if *score >= threshold { Some(hit) } else { None }
129	        })
130	        .filter(|hit| {
131	            // Session/Repo hits (no turn content) are not subject to the cap.
132	            let Some(sid) = &hit.session_id else { return true; };
133	            if matches!(hit.kind, HitKind::Session | HitKind::Repo) { return true; }
134	            let count = session_hit_counts.entry(sid.clone()).or_insert(0);
135	            if *count < MAX_HITS_PER_SESSION { *count += 1; true } else { false }
136	        })
137	        .take(top_k)
138	        .collect();
139	
140	    for hit in search_sessions_by_name(query) {
141	        let already = hits.iter().any(|h| {
142	            matches!(h.kind, HitKind::Session) && h.session_id == hit.session_id
143	        });
144	        if !already { hits.insert(0, hit); }
145	    }
146	    for hit in search_repos_by_name(query) {
147	        let already = hits.iter().any(|h| {
148	            matches!(h.kind, HitKind::Repo) && h.repo_dir == hit.repo_dir
149	        });
150	        if !already { hits.insert(0, hit); }
151	    }
152	    hits.truncate(top_k);
153	    enrich_hits(&mut hits);
154	
155	    let groups = build_groups(hits);
156	
157	    if json || !io::stdout().is_terminal() {
158	        let arr: Vec<serde_json::Value> = groups.iter().filter(|g| !matches!(g.kind, HitKind::RepoHeader)).map(|g| {
159	            let hits_json: Vec<serde_json::Value> = g.rows.iter().map(|r| serde_json::json!({
160	                "timestamp": r.hit_ts,
161	                "excerpt": r.lines.join(" "),
162	            })).collect();
163	            serde_json::json!({
164	                "kind": g.kind.label(),
165	                "session_id": g.session_id,
166	                "session_name": g.title,
167	                "dir": g.dir,
168	                "branch": g.branch,
169	                "author": g.author,
170	                "agent": g.agent,
171	                "updated_at": g.updated_at,
172	                "backed_up": g.backed_up,
173	                "remote": g.remote,
174	                "hits": hits_json,
175	            })
176	        }).collect();
177	        println!("{}", serde_json::to_string_pretty(&serde_json::json!({
178	            "query": query,
179	            "results": arr,
180	        }))?);
181	        return Ok(false);
182	    }
183	
184	    let orig_hook = std::panic::take_hook();
185	    std::panic::set_hook(Box::new(move |info| {
186	        let mut out = io::stdout();
187	        let _ = execute!(out, LeaveAlternateScreen, cursor::Show);
188	        let _ = terminal::disable_raw_mode();
189	        orig_hook(info);
190	    }));
191	
192	    let mut stdout = io::stdout();
193	    terminal::enable_raw_mode()?;
194	    execute!(stdout, EnterAlternateScreen, cursor::Hide)?;
195	
196	    let result = tui_loop(&mut stdout, &groups, query, ms);
197	
198	    execute!(stdout, LeaveAlternateScreen, cursor::Show)?;
199	    terminal::disable_raw_mode()?;
200	
201	    result
202	}
203	
204	/// The ingest pipeline prefixes user turns with `[User] ` so the embedded
205	/// body string distinguishes roles. The author column now carries that
206	/// information at the row level, so strip the inline tag from excerpts.
207	fn strip_user_label(s: &str) -> String {
208	    s.strip_prefix("[User] ")
209	        .or_else(|| s.strip_prefix("[User]"))
210	        .unwrap_or(s)
211	        .to_string()
212	}
213	
214	// ── Hit parsing ───────────────────────────────────────────────────────────────
215	
216	fn parse_hit(metadata_json: &str, bodies: &[String], sub_idx: u32) -> SearchHit {
217	    let sub_idx = sub_idx as usize;
218	    let meta: serde_json::Value = serde_json::from_str(metadata_json).unwrap_or_default();
219	    let source = meta["source"].as_str().unwrap_or("claude");
220	
221	    match source {
222	        "session" => {
223	            let name = meta["session_name"].as_str().unwrap_or("").to_string();
224	            let cwd  = meta["cwd"].as_str().unwrap_or("").to_string();
225	            SearchHit {
226	                kind: HitKind::Session,
227	                title: name,
228	                dir: super::short_path(&cwd),
229	                excerpt_lines: vec![], match_line_idx: 0,
230	                session_id: meta["session_id"].as_str().map(str::to_string),
231	                repo_dir: None,
232	                turn_id: None, hit_ts: None, hit_off: None, checkpoint_id: None, branch: String::new(),
233	                agent: String::new(), backed_up: false, updated_at: String::new(), author: String::new(),
234	                remote: String::new(), repo_name: String::new(),
235	            }
236	        }
237	        "repo" => {
238	            let name = meta["repo_name"].as_str().unwrap_or("").to_string();
239	            let dir  = meta["repo_dir"].as_str().unwrap_or("").to_string();
240	            SearchHit {
241	                kind: HitKind::Repo,
242	                title: name,
243	                dir: super::short_path(&dir),
244	                excerpt_lines: vec![], match_line_idx: 0,
245	                session_id: None,
246	                repo_dir: Some(dir),
247	                turn_id: None, hit_ts: None, hit_off: None, checkpoint_id: None, branch: String::new(),
248	                agent: String::new(), backed_up: false, updated_at: String::new(), author: String::new(),
249	                remote: String::new(), repo_name: String::new(),
250	            }
251	        }
252	        "checkpoint" => {
253	            let name    = meta["session_name"].as_str().unwrap_or("").to_string();
254	            let project = meta["project"].as_str().unwrap_or("").to_string();
255	            let message = bodies.first()
256	                .and_then(|b| b.lines().find(|l| l.starts_with("[Checkpoint] ")))
257	                .map(|l| l.trim_start_matches("[Checkpoint] ").to_string())
258	                .unwrap_or_default();
259	            SearchHit {
260	                kind: HitKind::Checkpoint,
261	                title: name,
262	                dir: super::short_path(&project),
263	                excerpt_lines: if message.is_empty() { vec![] } else { vec![message] },
264	                match_line_idx: 0,
265	                session_id: meta["session_id"].as_str().map(str::to_string),
266	                repo_dir: None,
267	                turn_id: None,
268	                hit_ts: None,
269	                hit_off: None,
270	                checkpoint_id: meta["checkpoint_id"].as_str().map(str::to_string),
271	                branch: String::new(),
272	                agent: String::new(), backed_up: false, updated_at: String::new(),
273	                author: String::new(), remote: String::new(), repo_name: String::new(),
274	            }
275	        }
276	        _ => {
277	            // "claude" — session log turn.
278	            // sub_idx=0 means the [project] header line matched — not a useful
279	            // content hit (session-name matching is handled separately). Drop it.
280	            if sub_idx == 0 {
281	                return SearchHit {
282	                    kind: HitKind::Session,
283	                    title: meta["session_name"].as_str().unwrap_or("").to_string(),
284	                    dir: super::short_path(meta["project"].as_str().unwrap_or("")),
285	                    excerpt_lines: vec![], match_line_idx: 0,
286	                    session_id: meta["session_id"].as_str().map(str::to_string),
287	                    repo_dir: None,
288	                    turn_id: None, hit_ts: None, hit_off: None, checkpoint_id: None,
289	                    branch: meta["branch"].as_str().unwrap_or("").to_string(),
290	                    agent: String::new(), backed_up: false, updated_at: String::new(),
291	                    author: String::new(), remote: String::new(), repo_name: String::new(),
292	                };
293	            }
294	
295	            let name    = meta["session_name"].as_str().unwrap_or("").to_string();
296	            let project = meta["project"].as_str().unwrap_or("").to_string();
297	            let branch  = meta["branch"].as_str().unwrap_or("").to_string();
298	
299	            let mut excerpt_lines: Vec<String> = Vec::new();
300	            // Track which line in excerpt_lines is the actual match (not context).
301	            let mut match_line_idx: usize = 0;
302	            if sub_idx > 1 {
303	                if let Some(prev) = bodies.get(sub_idx - 1) {
304	                    let t: String = strip_user_label(prev.trim()).chars().take(220).collect();
305	                    if !t.is_empty() {
306	                        excerpt_lines.push(t);
307	                        match_line_idx = excerpt_lines.len(); // matched line will follow
308	                    }
309	                }
310	            }
311	            if let Some(matched) = bodies.get(sub_idx) {
312	                let t: String = strip_user_label(matched.trim()).chars().take(400).collect();
313	                if !t.is_empty() {
314	                    match_line_idx = excerpt_lines.len();
315	                    excerpt_lines.push(t);
316	                }
317	            }
318	            if sub_idx + 1 < bodies.len() {
319	                if let Some(next) = bodies.get(sub_idx + 1) {
320	                    let t: String = strip_user_label(next.trim()).chars().take(220).collect();
321	                    if !t.is_empty() { excerpt_lines.push(t); }
322	                }
323	            }
324	
325	            // sub_idx 0 = header matched, 1+ = turns[sub_idx-1] matched.
326	            let turn_meta = if sub_idx > 0 { &meta["turns"][sub_idx - 1] } else { &serde_json::Value::Null };
327	            let hit_ts  = turn_meta["timestamp"].as_str().filter(|s| !s.is_empty()).map(str::to_string);
328	            let turn_id = turn_meta["uuid"].as_str().filter(|s| !s.is_empty()).map(str::to_string);
329	            let hit_off = turn_meta["off"].as_u64();
330	
331	            SearchHit {
332	                kind: HitKind::Log,
333	                title: name,
334	                dir: super::short_path(&project),
335	                excerpt_lines,
336	                match_line_idx,
337	                session_id: meta["session_id"].as_str().map(str::to_string),
338	                repo_dir: None,
339	                turn_id,
340	                hit_ts,
341	                hit_off,
342	                checkpoint_id: None,
343	                branch,
344	                agent: String::new(), backed_up: false, updated_at: String::new(), author: String::new(),
345	                remote: String::new(), repo_name: String::new(),
346	            }
347	        }
348	    }
349	}
350	
351	// ── Group building ────────────────────────────────────────────────────────────
352	
353	// Each hit becomes its own selectable group — one header row + one excerpt row.
354	// We do not merge multiple hits from the same session; that produced a wall of
355	// text that couldn't be navigated individually.
356	const MAX_HITS_PER_SESSION: usize = 3;
357	
358	fn build_groups(hits: Vec<SearchHit>) -> Vec<Group> {
359	    let mut groups: Vec<Group> = Vec::new();
360	    let mut hits_per_session: std::collections::HashMap<String, usize> = std::collections::HashMap::new();
361	
362	    for hit in hits {
363	        match hit.kind {
364	            HitKind::Log | HitKind::Checkpoint => {
365	                let is_cp = matches!(hit.kind, HitKind::Checkpoint);
366	                // Log hits with no excerpt are header-only matches (sub_idx==0);
367	                // they produce blank rows and convey nothing useful — drop them.
368	                if !is_cp && hit.excerpt_lines.is_empty() {
369	                    continue;
370	                }
371	                // Cap per-session hits so one very-relevant session doesn't
372	                // consume all result slots.
373	                if let Some(sid) = &hit.session_id {
374	                    let n = hits_per_session.entry(sid.clone()).or_insert(0);
375	                    if *n >= MAX_HITS_PER_SESSION { continue; }
376	                    *n += 1;
377	                }
378	                groups.push(Group {
379	                    title: hit.title,
380	                    dir: hit.dir,
381	                    branch: hit.branch,
382	                    agent: hit.agent,
383	                    backed_up: hit.backed_up,
384	                    updated_at: hit.updated_at,
385	                    remote: hit.remote,
386	                    repo_name: hit.repo_name,
387	                    session_id: hit.session_id,
388	                    repo_dir: None,
389	                    kind: if is_cp { HitKind::Checkpoint } else { HitKind::Log },
390	                    author: hit.author,
391	                    rows: vec![GroupRow {
392	                        hit_ts: hit.hit_ts,
393	                        hit_off: hit.hit_off,
394	                        turn_id: hit.turn_id,
395	                        checkpoint_id: hit.checkpoint_id,
396	                        lines: hit.excerpt_lines,
397	                        match_line_idx: hit.match_line_idx,
398	                        is_checkpoint: is_cp,
399	                    }],
400	                });
401	            }
402	            HitKind::Session => {
403	                // Skip if this session already appeared as a Log/Checkpoint hit,
404	                // or if we've already emitted a Session hit for it.
405	                if let Some(sid) = &hit.session_id {
406	                    let n = hits_per_session.entry(sid.clone()).or_insert(0);
407	                    if *n > 0 { continue; }
408	                    *n += 1;
409	                }
410	                groups.push(Group {
411	                    title: hit.title,
412	                    dir: hit.dir,
413	                    branch: String::new(),
414	                    agent: hit.agent,
415	                    backed_up: hit.backed_up,
416	                    updated_at: hit.updated_at,
417	                    remote: hit.remote,
418	                    repo_name: hit.repo_name,
419	                    session_id: hit.session_id,
420	                    repo_dir: None,
421	                    kind: HitKind::Session,
422	                    author: hit.author,
423	                    rows: vec![],
424	                });
425	            }
426	            HitKind::Repo => {
427	                groups.push(Group {
428	                    title: hit.title,
429	                    dir: hit.dir,
430	                    branch: String::new(),
431	                    agent: String::new(),
432	                    backed_up: false,
433	                    updated_at: String::new(),
434	                    remote: hit.remote,
435	                    repo_name: hit.repo_name,
436	                    session_id: None,
437	                    repo_dir: hit.repo_dir,
438	                    kind: HitKind::Repo,
439	                    author: String::new(),
440	                    rows: vec![],
441	                });
442	            }
443	            HitKind::RepoHeader => {} // never produced by parse_hit
444	        }
445	    }
446	
447	    // Stable sort by repo_name (falling back to dir) so hits from the same
448	    // repo cluster together while preserving relevance ordering within each repo.
449	    groups.sort_by(|a, b| {
450	        let ka = if !a.repo_name.is_empty() { &a.repo_name } else { &a.dir };
451	        let kb = if !b.repo_name.is_empty() { &b.repo_name } else { &b.dir };
452	        ka.cmp(kb)
453	    });
454	
455	    // Inject a non-selectable RepoHeader sentinel before each new repo.
456	    let mut with_headers: Vec<Group> = Vec::with_capacity(groups.len() + 4);
457	    let mut current_key = String::new();
458	    for g in groups {
459	        let key = if !g.repo_name.is_empty() { g.repo_name.clone() } else { g.dir.clone() };
460	        if key != current_key {
461	            current_key = key.clone();
462	            with_headers.push(Group {
463	                title: key,
464	                dir: String::new(), branch: String::new(), agent: String::new(),
465	                backed_up: false, updated_at: String::new(), remote: String::new(),
466	                repo_name: String::new(), session_id: None, repo_dir: None,
467	                kind: HitKind::RepoHeader, rows: vec![], author: String::new(),
468	            });
469	        }
470	        with_headers.push(g);
471	    }
472	    with_headers
473	}
474	
475	// ── TUI ───────────────────────────────────────────────────────────────────────
476	
477	fn tui_loop(stdout: &mut impl Write, groups: &[Group], query: &str, ms: u128) -> Result<bool> {
478	    let mut sel    = first_selectable(groups);
479	    let mut scroll = 0usize;
480	    let mut quit_app = false;
481	
482	    loop {
483	        let (w, h) = terminal::size().unwrap_or((120, 40));
484	        let w = w as usize;
485	        let h = h as usize;
486	        let content_h = h.saturating_sub(2);
487	
488	        let sel_start = group_start_of(groups, sel);
489	        let sel_end   = sel_start + groups.get(sel).map_or(1, rows_for_group);
490	        if sel_start < scroll                { scroll = sel_start; }
491	        else if sel_end > scroll + content_h { scroll = sel_end.saturating_sub(content_h); }
492	
493	        draw(stdout, groups, query, ms, sel, scroll, w, h)?;
494	
495	        match event::read()? {
496	            Event::Key(k) => match k.code {
497	                KeyCode::Char('q') => { quit_app = true; break; }
498	                KeyCode::Esc | KeyCode::Left => break,
499	                KeyCode::Char('c') if k.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) => {
500	                    execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
501	                    terminal::disable_raw_mode().ok();
502	                    std::process::exit(0);
503	                }
504	                KeyCode::Up   | KeyCode::Char('k') => { sel = prev_selectable(groups, sel); }
505	                KeyCode::Down | KeyCode::Char('j') => { sel = next_selectable(groups, sel); }
506	                KeyCode::Char('g') => { sel = first_selectable(groups); scroll = 0; }
507	                KeyCode::Char('G') => { sel = last_selectable(groups); }
508	                KeyCode::Char(' ') | KeyCode::Right | KeyCode::Enter => {
509	                    if let Some(group) = groups.get(sel) {
510	                        execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
511	                        terminal::disable_raw_mode().ok();
512	
513	                        let nested_quit = match group.kind {
514	                            HitKind::Log | HitKind::Checkpoint | HitKind::Session => {
515	                                if let Some(id) = &group.session_id {
516	                                    let tid  = group.rows.first().and_then(|r| r.turn_id.as_deref());
517	                                    let hts  = group.rows.first().and_then(|r| r.hit_ts.as_deref());
518	                                    let hoff = group.rows.first().and_then(|r| r.hit_off);
519	                                    let cpid = group.rows.first().and_then(|r| r.checkpoint_id.as_deref());
520	                                    super::show::run_at(id, tid, hts, hoff, cpid).unwrap_or(false)
521	                                } else { false }
522	                            }
523	                            HitKind::Repo => {
524	                                if let Some(dir) = &group.repo_dir {
525	                                    let _ = super::status::run_for_dir(dir);
526	                                }
527	                                false
528	                            }
529	                            HitKind::RepoHeader => false,
530	                        };
531	
532	                        if nested_quit { quit_app = true; break; }
533	
534	                        terminal::enable_raw_mode().ok();
535	                        execute!(stdout, EnterAlternateScreen, cursor::Hide).ok();
536	                        execute!(stdout, terminal::Clear(ClearType::All)).ok();
537	                    }
538	                }
539	                _ => {}
540	            },
541	            Event::Resize(_, _) => {
542	                execute!(stdout, terminal::Clear(ClearType::All)).ok();
543	            }
544	            _ => {}
545	        }
546	    }
547	
548	    Ok(quit_app)
549	}
550	
551	fn rows_for_group(g: &Group) -> usize {
552	    if matches!(g.kind, HitKind::RepoHeader) { return 1; }
553	    1 + g.rows.iter().map(|r| r.lines.len().max(1)).sum::<usize>() + 1 // +1 for blank separator
554	}
555	
556	fn is_selectable(g: &Group) -> bool {
557	    !matches!(g.kind, HitKind::RepoHeader)
558	}
559	
560	fn next_selectable(groups: &[Group], from: usize) -> usize {
561	    (from + 1..groups.len()).find(|&i| is_selectable(&groups[i])).unwrap_or(from)
562	}
563	
564	fn prev_selectable(groups: &[Group], from: usize) -> usize {
565	    (0..from).rev().find(|&i| is_selectable(&groups[i])).unwrap_or(from)
566	}
567	
568	fn first_selectable(groups: &[Group]) -> usize {
569	    groups.iter().position(is_selectable).unwrap_or(0)
570	}
571	
572	fn last_selectable(groups: &[Group]) -> usize {
573	    groups.iter().rposition(is_selectable).unwrap_or(0)
574	}
575	
576	fn group_start_of(groups: &[Group], idx: usize) -> usize {
577	    groups[..idx.min(groups.len())].iter().map(rows_for_group).sum()
578	}
579	
580	// ── Rendering ─────────────────────────────────────────────────────────────────
581	
582	fn draw(
583	    stdout: &mut impl Write,
584	    groups: &[Group],
585	    query:  &str,
586	    ms:     u128,
587	    sel:    usize,
588	    scroll: usize,
589	    w:      usize,
590	    h:      usize,
591	) -> io::Result<()> {
592	    use crossterm::queue;
593	    let t = crate::theme::get();
594	    const TS_W: usize = 12; // fixed width of the timestamp column in excerpt rows
595	
596	    let content_h = h.saturating_sub(2);
597	    let mut buf: Vec<u8> = Vec::with_capacity((w + 60) * (h + 2));
598	
599	    // Title bar
600	    queue!(buf, cursor::MoveTo(0, 0), terminal::Clear(ClearType::UntilNewLine))?;
601	    let result_count = groups.iter().filter(|g| is_selectable(g)).count();
602	    let hdr = format!("  search: \"{}\"  {} result(s)  {}ms", query, result_count, ms);
603	    write!(buf, "\x1b[1m{}\x1b[0m", hdr.chars().take(w).collect::<String>())?;
604	
605	    // Pre-compute column widths across all groups for tabular alignment.
606	    let name_w   = groups.iter().map(|g| g.title.trim().chars().count()).max().unwrap_or(0).min(45);
607	    let agent_w  = groups.iter().map(|g| g.agent.chars().count()).max().unwrap_or(0);
608	    let author_w = groups.iter().map(|g| g.author.chars().count()).max().unwrap_or(0);
609	    let branch_w = groups.iter().map(|g| g.branch.chars().count()).max().unwrap_or(0).min(30);
610	
611	    let accent = t.accent;
612	    // Write one content line into the buffer using the ▌ bar for selection.
613	    let mut write_row = |buf: &mut Vec<u8>, line: &str, selected: bool, screen_row: usize| -> io::Result<()> {
614	        queue!(buf, cursor::MoveTo(0, screen_row as u16), terminal::Clear(ClearType::UntilNewLine))?;
615	        if selected {
616	            write!(buf, "\x1b[{accent}m▌\x1b[0m {line}")?;
617	        } else {
618	            write!(buf, "  {line}")?;
619	        }
620	        Ok(())
621	    };
622	
623	    let mut screen_row = 1usize; // next terminal row to write (row 0 is title bar)
624	    let mut abs_row    = 0usize; // absolute content row (before scroll is applied)
625	
626	    for (gi, group) in groups.iter().enumerate() {
627	        if screen_row > content_h { break; }
628	        let selected = gi == sel;
629	
630	        // ── Repo section header (non-selectable) ─────────────────────────
631	        if matches!(group.kind, HitKind::RepoHeader) {
632	            if abs_row >= scroll && screen_row <= content_h {
633	                queue!(buf, cursor::MoveTo(0, screen_row as u16), terminal::Clear(ClearType::UntilNewLine))?;
634	                let label = &group.title;
635	                let dash_w = w.saturating_sub(label.chars().count() + 5);
636	                let dashes: String = "─".repeat(dash_w.min(w));
637	                write!(buf, "  \x1b[{lk}m{label}\x1b[0m \x1b[{dm}m{dashes}\x1b[0m",
638	                    lk = t.link, dm = t.text_dim)?;
639	                screen_row += 1;
640	            }
641	            abs_row += 1;
642	            continue;
643	        }
644	
645	        // ── Session header ────────────────────────────────────────────────
646	        if abs_row >= scroll && screen_row <= content_h {
647	            let age     = age_secs_hit(&group.updated_at);
648	            let dot_col = match age {
649	                a if a < 900   => t.fresh,
650	                a if a < 3_600 => t.moderate,
651	                _              => t.text_dim,
652	            };
653	            let (name_col, meta_col, dot_char) = if group.backed_up {
654	                (t.backed_name, t.backed_meta, "★")
655	            } else {
656	                (t.unbacked_name, t.unbacked_meta, "·")
657	            };
658	
659	            let name: String = group.title.trim().chars().take(name_w).collect();
660	            let name_padded  = format!("{name:<name_w$}");
661	            let mut line = format!(
662	                "\x1b[{dot_col}m{dot_char}\x1b[0m \x1b[{name_col}m{name_padded}\x1b[0m  \x1b[{dm}m{}\x1b[0m",
663	                group.dir, dm = t.text_dim,
664	            );
665	
666	            if branch_w > 0 {
667	                let branch_col = if group.backed_up { t.link } else { t.stale };
668	                let b: String = group.branch.chars().take(branch_w).collect();
669	                let pad = " ".repeat(branch_w - b.chars().count());
670	                line.push_str(&format!("  \x1b[{branch_col}m{b}{pad}\x1b[0m"));
671	            }
672	
673	            if author_w > 0 {
674	                let a: String = group.author.chars().take(author_w).collect();
675	                let pad = " ".repeat(author_w - a.chars().count());
676	                let col = super::author_color(&group.author);
677	                line.push_str(&format!("  \x1b[38;5;{col}m{a}\x1b[0m{pad}"));
678	            }
679	
680	            if agent_w > 0 {
681	                let a: String = group.agent.chars().take(agent_w).collect();
682	                let pad = " ".repeat(agent_w - a.chars().count());
683	                if group.backed_up {
684	                    let col = agent_color(&group.agent);
685	                    line.push_str(&format!("  \x1b[38;5;{col}m{a}{pad}\x1b[0m"));
686	                } else {
687	                    line.push_str(&format!("  \x1b[{st}m{a}{pad}\x1b[0m", st = t.stale));
688	                }
689	            }
690	
691	            if let Some(sid) = &group.session_id {
692	                let id_short: String = sid.chars().take(8).collect();
693	                let ts = rel_time_hit(&group.updated_at);
694	                line.push_str(&format!("  \x1b[{meta_col}m{id_short}  {ts}\x1b[0m"));
695	            } else if matches!(group.kind, HitKind::Repo) {
696	                line.push_str(&format!("  \x1b[{meta_col}mrepo\x1b[0m"));
697	            }
698	
699	            // Header row: full background highlight so the session name pops.
700	            super::render_row(&mut buf, &line, selected, screen_row, w)?;
701	            screen_row += 1;
702	        }
703	        abs_row += 1;
704	
705	        // ── Excerpt rows ──────────────────────────────────────────────────
706	        for row in &group.rows {
707	            let ts_str = row.hit_ts.as_deref().map(rel_time_hit).unwrap_or_default();
708	            let n_lines = row.lines.len().max(1);
709	            let excerpt_indent = " ".repeat(2 + TS_W + 2);
710	
711	            for li in 0..n_lines {
712	                if abs_row >= scroll && screen_row <= content_h {
713	                    let text = row.lines.get(li).map(String::as_str).unwrap_or("");
714	                    let avail = w.saturating_sub(2 + TS_W + 2);
715	                    // Matched line is brighter than context lines.
716	                    let is_match_line = li == row.match_line_idx;
717	                    let line_color = if is_match_line { t.text_primary } else { t.text_secondary };
718	                    let match_marker = if is_match_line { "▶ " } else { "  " };
719	
720	                    let exc_line = if li == 0 && row.is_checkpoint {
721	                        let ts_padded = format!("{ts_str:>TS_W$}");
722	                        let avail2 = avail.saturating_sub(5 + 2); // [cp] + marker
723	                        let text_t: String = text.chars().take(avail2).collect();
724	                        format!(
725	                            "  \x1b[{dm}m{ts_padded}\x1b[0m  \x1b[{lb}m[cp]\x1b[0m {match_marker}\x1b[{lc}m{text_t}\x1b[0m",
726	                            dm = t.text_dim, lb = t.label, lc = line_color,
727	                        )
728	                    } else if li == 0 {
729	                        let ts_padded = format!("{ts_str:>TS_W$}");
730	                        let avail2 = avail.saturating_sub(2); // marker
731	                        let text_t: String = text.chars().take(avail2).collect();
732	                        format!(
733	                            "  \x1b[{dm}m{ts_padded}\x1b[0m  {match_marker}\x1b[{lc}m{text_t}\x1b[0m",
734	                            dm = t.text_dim, lc = line_color,
735	                        )
736	                    } else {
737	                        let avail2 = avail.saturating_sub(2); // marker
738	                        let text_t: String = text.chars().take(avail2).collect();
739	                        format!("{excerpt_indent}{match_marker}\x1b[{lc}m{text_t}\x1b[0m", lc = line_color)
740	                    };
741	
742	                    // Excerpt rows: ▌ bar ties them visually to the selected header.
743	                    write_row(&mut buf, &exc_line, selected, screen_row)?;
744	                    screen_row += 1;
745	                }
746	                abs_row += 1;
747	            }
748	        }
749	
750	        // Blank separator row between groups
751	        if abs_row >= scroll && screen_row <= content_h {
752	            queue!(buf, cursor::MoveTo(0, screen_row as u16), terminal::Clear(ClearType::UntilNewLine))?;
753	            screen_row += 1;
754	        }
755	        abs_row += 1;
756	    }
757	
758	    // Clear any leftover rows below the results.
759	    while screen_row <= content_h {
760	        queue!(buf, cursor::MoveTo(0, screen_row as u16), terminal::Clear(ClearType::UntilNewLine))?;
761	        screen_row += 1;
762	    }
763	
764	    super::draw_statusbar(&mut buf, "  ↑↓/jk: navigate   space/→: open   ←/esc: back   q: quit  ", w, h)?;
765	
766	    stdout.write_all(&buf)?;
767	    stdout.flush()
768	}
769	
770	
771	// ── DB enrichment ─────────────────────────────────────────────────────────────
772	
773	fn enrich_hits(hits: &mut Vec<SearchHit>) {
774	    let Ok(conn) = crate::db::connect() else { return };
775	    for hit in hits.iter_mut() {
776	        if let Some(sid) = &hit.session_id {
777	            // Pull agent + remote + repo_name, plus the first checkpoint's author.
778	            if let Ok((agent, updated_at, remote, repo_name, author_name, author_email, author_os_user)) =
779	                conn.query_row(
780	                    "SELECT s.agent_name, s.updated_at, COALESCE(r.remote, ''),
781	                            COALESCE(r.name, ''),
782	                            COALESCE(c.author_name, ''), COALESCE(c.author_email, ''),
783	                            COALESCE(c.os_user, '')
784	                     FROM sessions s
785	                     LEFT JOIN repositories r
786	                       ON (s.cwd = r.directory OR s.cwd LIKE r.directory || '/%')
787	                     LEFT JOIN checkpoints c
788	                       ON c.session_id = s.session_id
789	                      AND c.checkpoint_id = (
790	                            SELECT checkpoint_id FROM checkpoints
791	                            WHERE session_id = s.session_id
792	                            ORDER BY last_turn_ts ASC LIMIT 1
793	                          )
794	                     WHERE s.session_id = ?1",
795	                    [sid.as_str()],
796	                    |row| Ok((
797	                        row.get::<_, String>(0)?,
798	                        row.get::<_, String>(1)?,
799	                        row.get::<_, String>(2)?,
800	                        row.get::<_, String>(3)?,
801	                        row.get::<_, String>(4)?,
802	                        row.get::<_, String>(5)?,
803	                        row.get::<_, String>(6)?,
804	                    )),
805	                )
806	            {
807	                hit.agent      = agent;
808	                hit.updated_at = updated_at;
809	                hit.backed_up  = true;
810	                hit.remote     = remote;
811	                hit.repo_name  = repo_name;
812	                hit.author     = if !author_name.trim().is_empty() { author_name }
813	                                 else if !author_email.trim().is_empty() { author_email }
814	                                 else { author_os_user };
815	            }
816	        } else if let Some(dir) = &hit.repo_dir.clone() {
817	            if let Ok((remote, repo_name)) = conn.query_row(
818	                "SELECT COALESCE(remote, ''), COALESCE(name, '') FROM repositories WHERE directory = ?1",
819	                [dir.as_str()],
820	                |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?)),
821	            ) {
822	                hit.remote    = remote;
823	                hit.repo_name = repo_name;
824	            }
825	        }
826	    }
827	}
828	
829	// ── Direct name search ────────────────────────────────────────────────────────
830	
831	fn search_sessions_by_name(query: &str) -> Vec<SearchHit> {
832	    let words: Vec<String> = query.split_whitespace().map(|w| w.to_lowercase()).collect();
833	    if words.is_empty() { return vec![]; }
834	
835	    let Ok(conn) = crate::db::connect() else { return vec![]; };
836	    let Ok(mut stmt) = conn.prepare(
837	        "SELECT session_id, session_name, cwd FROM sessions WHERE session_name != ''"
838	    ) else { return vec![]; };
839	
840	    stmt.query_map([], |row| Ok((row.get::<_,String>(0)?, row.get::<_,String>(1)?, row.get::<_,String>(2)?)))
841	        .ok()
842	        .into_iter()
843	        .flatten()
844	        .flatten()
845	        .filter_map(|(session_id, session_name, cwd): (String, String, String)| {
846	            let normalized = session_name.to_lowercase().replace(['-', '_'], " ");
847	            if words.iter().all(|w| normalized.contains(w.as_str())) {
848	                Some(SearchHit {
849	                    kind: HitKind::Session,
850	                    title: session_name,
851	                    dir: super::short_path(&cwd),
852	                    excerpt_lines: vec![], match_line_idx: 0,
853	                    session_id: Some(session_id),
854	                    repo_dir: None,
855	                    turn_id: None, hit_ts: None, hit_off: None, checkpoint_id: None, branch: String::new(),
856	                    agent: String::new(), backed_up: false, updated_at: String::new(), author: String::new(),
857	                    remote: String::new(), repo_name: String::new(),
858	                })
859	            } else {
860	                None
861	            }
862	        })
863	        .collect()
864	}
865	
866	fn search_repos_by_name(query: &str) -> Vec<SearchHit> {
867	    let words: Vec<String> = query.split_whitespace().map(|w| w.to_lowercase()).collect();
868	    if words.is_empty() { return vec![]; }
869	
870	    let Ok(conn) = crate::db::connect() else { return vec![]; };
871	    let Ok(mut stmt) = conn.prepare(
872	        "SELECT name, directory, COALESCE(remote, '') FROM repositories WHERE name != ''"
873	    ) else { return vec![]; };
874	
875	    stmt.query_map([], |row| Ok((row.get::<_,String>(0)?, row.get::<_,String>(1)?, row.get::<_,String>(2)?)))
876	        .ok()
877	        .into_iter()
878	        .flatten()
879	        .flatten()
880	        .filter_map(|(name, directory, remote): (String, String, String)| {
881	            let normalized = name.to_lowercase().replace(['-', '_'], " ");
882	            if words.iter().all(|w| normalized.contains(w.as_str())) {
883	                Some(SearchHit {
884	                    kind: HitKind::Repo,
885	                    title: name.clone(),
886	                    dir: super::short_path(&directory),
887	                    excerpt_lines: vec![], match_line_idx: 0,
888	                    session_id: None,
889	                    repo_dir: Some(directory),
890	                    turn_id: None, hit_ts: None, hit_off: None, checkpoint_id: None, branch: String::new(),
891	                    agent: String::new(), backed_up: false, updated_at: String::new(), author: String::new(),
892	                    remote, repo_name: name,
893	                })
894	            } else {
895	                None
896	            }
897	        })
898	        .collect()
899	}
900	
901	// ── Helpers ───────────────────────────────────────────────────────────────────
902	
903	fn rel_time_hit(iso: &str) -> String {
904	    if iso.is_empty() { return String::new(); }
905	    let Ok(dt) = DateTime::parse_from_rfc3339(iso) else { return String::new(); };
906	    let secs = (Utc::now() - dt.with_timezone(&Utc)).num_seconds().max(0);
907	    if secs < 604_800 {
908	        match secs {
909	            s if s < 60     => "just now".into(),
910	            s if s < 3_600  => format!("{} min ago", s / 60),
911	            s if s < 86_400 => format!("{} hr ago",  s / 3_600),
912	            s               => format!("{} day{} ago", s / 86_400, if s / 86_400 == 1 { "" } else { "s" }),
913	        }
914	    } else {
915	        dt.with_timezone(&chrono::Local).format("%m/%d/%y").to_string()
916	    }
917	}
918	
919	fn age_secs_hit(iso: &str) -> i64 {
920	    if iso.is_empty() { return i64::MAX; }
921	    let Ok(dt) = DateTime::parse_from_rfc3339(iso) else { return i64::MAX; };
922	    (Utc::now() - dt.with_timezone(&Utc)).num_seconds().max(0)
923	}
