163	/// Strip a leading `/Users/<x>/` or `/home/<x>/` prefix from a path. Returns
164	/// the remainder (project-relative path). None if the path doesn't start with
165	/// a recognized home prefix or has nothing after the username segment.
166	fn strip_user_home(path: &str) -> Option<&str> {
167	    for home_root in ["/Users/", "/home/"] {
168	        if let Some(rest) = path.strip_prefix(home_root) {
169	            return rest.split_once('/').map(|(_user, after)| after);
170	        }
171	    }
172	    None
173	}
