175	/// Like `starts_with` but only matches at a path boundary, so
176	/// `cosmos/cosmos-graphql-foo` does NOT match prefix `cosmos/cosmos-graphql`.
177	fn path_prefix_match(haystack: &str, needle: &str) -> bool {
178	    if haystack == needle { return true; }
179	    if !haystack.starts_with(needle) { return false; }
180	    // Char immediately after the needle must be a path separator.
181	    haystack.as_bytes().get(needle.len()) == Some(&b'/')
182	}
