224	/// Walk ~/.claude/projects/**/*.jsonl and upsert any session whose UUID
225	/// isn't already in the DB. Picks up sessions that ran before `gossamer init`
226	/// installed the session-start hook, plus any session that for whatever
227	/// reason never got captured by entire's checkpoint branch.
228	pub(crate) fn backfill_local_jsonls(
229	    conn: &rusqlite::Connection,
230	    _repos: &[(i64, String, String)],
231	    resolver: &RepoResolver,
232	) -> Result<usize> {
233	    let home = std::env::var("HOME").map_err(|_| anyhow::anyhow!("HOME unset"))?;
234	    let projects = std::path::PathBuf::from(&home).join(".claude/projects");
235	    let Ok(dirs) = std::fs::read_dir(&projects) else { return Ok(0); };
236	
237	    let known: std::collections::HashSet<String> = {
238	        let mut out = std::collections::HashSet::new();
239	        if let Ok(mut stmt) = conn.prepare("SELECT session_id FROM sessions") {
240	            if let Ok(rows) = stmt.query_map([], |row| row.get::<_, String>(0)) {
241	                for r in rows.flatten() { out.insert(r); }
242	            }
243	        }
244	        out
245	    };
246	
247	    let user = std::env::var("USER")
248	        .or_else(|_| std::env::var("USERNAME"))
249	        .unwrap_or_else(|_| "unknown".to_string());
250	
251	    let mut count = 0usize;
252	    for dir in dirs.flatten() {
253	        let path = dir.path();
254	        if !path.is_dir() { continue; }
255	        let Ok(files) = std::fs::read_dir(&path) else { continue; };
256	        for f in files.flatten() {
257	            let p = f.path();
258	            if p.extension().and_then(|e| e.to_str()) != Some("jsonl") { continue; }
259	            let Some(sid) = p.file_stem().and_then(|s| s.to_str()).map(str::to_string) else { continue; };
260	            if known.contains(&sid) { continue; }
261	
262	            let Ok(bytes) = std::fs::read(&p) else { continue; };
263	            let parsed = match crate::parsers::dispatch_shadow_session(&bytes, &sid) {
264	                Ok(t) => t,
265	                Err(_) => continue,
266	            };
267	
268	            // No indexing context here — backfill doesn't know which repo's
269	            // branch this came from. Resolver tries cwd-prefix then git
270	            // remote; gives up if neither matches a tracked project.
271	            let repo_id = resolver.resolve(&parsed.cwd, None);
272	
273	            if upsert_session(conn, &parsed.session_id, &parsed.agent_name, &user,
274	                              &parsed.created_at, &parsed.updated_at, &parsed.cwd, &parsed.session_name,
275	                              &parsed.branch, repo_id, parsed.name_is_explicit, parsed.tokens_used).is_ok() {
276	                count += 1;
277	            }
278	        }
279	    }
280	    Ok(count)
281	}
