283	/// Extract the OS username from a session's cwd. The JSONL captures the cwd
284	/// on the machine that ran the conversation, so `/Users/sholodak/...` reliably
285	/// identifies Scott even when the checkpoint reached us via a merge commit.
286	pub(crate) fn cwd_to_os_user(cwd: &str) -> Option<String> {
287	    let rest = cwd.strip_prefix("/Users/")
288	        .or_else(|| cwd.strip_prefix("/home/"))?;
289	    let user = rest.split('/').next()?;
290	    if user.is_empty() { None } else { Some(user.to_string()) }
291	}
