293	pub fn run(json: bool) -> Result<()> {
294	    let conn = db::connect()?;
295	
296	    let mut stmt = conn.prepare("SELECT id, directory, name FROM repositories")?;
297	    let repos: Vec<(i64, String, String)> = stmt
298	        .query_map([], |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)))?
299	        .collect::<Result<_, _>>()?;
300	
301	    if repos.is_empty() {
302	        if json {
303	            println!("{}", serde_json::json!({"sessions_indexed": 0, "log_turns": 0}));
304	        } else {
305	            println!("No repositories tracked. Run `gossamer init` first.");
306	        }
307	        return Ok(());
308	    }
309	
310	    let resolver = RepoResolver::new(&conn)?;
311	
312	    let mut grand_total = 0usize;
313	
314	    for (repo_id, dir, name) in &repos {
315	        match index_repo(&conn, *repo_id, dir, name, &resolver) {
316	            Ok(0) => { if !json { println!("'{}': no {} branch found.", name, BRANCH); } }
317	            Ok(n) => {
318	                if !json { println!("'{}': indexed {} session(s).", name, n); }
319	                grand_total += n;
320	            }
321	            Err(e) => eprintln!("'{}': error — {}", name, e),
322	        }
323	    }
324	
325	    let backfilled = backfill_local_jsonls(&conn, &repos, &resolver).unwrap_or(0);
326	    if !json && backfilled > 0 {
327	        println!("Backfilled {} local session(s) from ~/.claude/projects.", backfilled);
328	    }
329	    grand_total += backfilled;
330	
331	    if !json { println!("\n{} session(s) indexed.", grand_total); }
332	
333	    if !json { println!("\nIndexing into search DB..."); }
334	    // Full re-index: clear per-repo watermarks so ingest_claude_code processes
335	    // every session, not just ones added since the last run.
336	    let _ = conn.execute("UPDATE repositories SET last_search_commit = NULL", []);
337	    let mut wc_db = ingest::open_search_db()?;
338	    let turns    = ingest::claude_code::ingest_claude_code(&mut wc_db)?;
339	    let sessions = ingest::ingest_sessions(&mut wc_db).unwrap_or(0);
340	    let repos_n  = ingest::ingest_repos(&mut wc_db).unwrap_or(0);
341	    if !json { println!("{turns} log turn(s), {sessions} session name(s), {repos_n} repo(s) indexed."); }
342	    ingest::embed_and_index(&wc_db)?;
343	
344	    if json {
345	        println!("{}", serde_json::to_string_pretty(&serde_json::json!({
346	            "sessions_indexed": grand_total,
347	            "log_turns": turns,
348	            "session_names": sessions,
349	            "repos": repos_n,
350	        }))?);
351	    }
352	
353	    Ok(())
354	}
