356	pub(crate) fn is_meta_path(l: &str) -> bool {
357	    l.ends_with("/metadata.json")
358	        && l.matches('/').count() == 3
359	        && l.split('/').nth(2).map_or(false, |s| s.chars().all(|c| c.is_ascii_digit()))
360	}
