362	fn index_repo(conn: &rusqlite::Connection, repo_id: i64, repo_dir: &str, _repo_name: &str, resolver: &RepoResolver) -> Result<usize> {
363	    fetch_checkpoint_branch(repo_dir);
364	
365	    let check = Command::new("git")
366	        .args(["rev-parse", "--verify", BRANCH])
367	        .current_dir(repo_dir)
368	        .output()
369	        .context("failed to run git")?;
370	
371	    if !check.status.success() {
372	        return Ok(0);
373	    }
374	
375	    let ls = Command::new("git")
376	        .args(["ls-tree", "-r", "--name-only", BRANCH])
377	        .current_dir(repo_dir)
378	        .output()
379	        .context("git ls-tree failed")?;
380	
381	    let listing = String::from_utf8(ls.stdout)?;
382	
383	    let meta_paths: Vec<&str> = listing.lines().filter(|l| is_meta_path(l)).collect();
384	
385	    let user = std::env::var("USER")
386	        .or_else(|_| std::env::var("USERNAME"))
387	        .unwrap_or_else(|_| "unknown".to_string());
388	
389	    // Path→author map built from non-merge commits only. Sessions that
390	    // arrived via "Merge remote session logs" batch imports are not in here —
391	    // they fall back to cwd-derived attribution below.
392	    let direct_authors = build_commit_authors(repo_dir).unwrap_or_default();
393	
394	    // Pass 1: parse every session, register session row, and accumulate
395	    // checkpoint info. We also learn os_user→author mappings from sessions
396	    // that have a direct (non-merge) commit, so we can attribute merge-only
397	    // sessions to the right human in pass 2.
398	    let mut pending: Vec<PendingCheckpoint> = Vec::new();
399	    let mut os_user_authors: HashMap<String, CommitAuthor> = HashMap::new();
400	
401	    for meta_path in meta_paths {
402	        let jsonl_path = format!("{}full.jsonl", &meta_path[..meta_path.len() - "metadata.json".len()]);
403	
404	        let meta_bytes = match git_show(repo_dir, meta_path) {
405	            Ok(b) => b,
406	            Err(e) => { eprintln!("  skipping {}: {}", meta_path, e); continue; }
407	        };
408	        let jsonl_bytes = match git_show(repo_dir, &jsonl_path) {
409	            Ok(b) => b,
410	            Err(_) => continue,
411	        };
412	
413	        let parsed = match crate::parsers::dispatch_session(&meta_bytes, &jsonl_bytes) {
414	            Ok(p) => p,
415	            Err(e) => { eprintln!("  skipping {}: {}", meta_path, e); continue; }
416	        };
417	
418	        let resolved_id = resolver.resolve(&parsed.cwd, Some(repo_id));
419	        upsert_session(conn, &parsed.session_id, &parsed.agent_name, &user,
420	                       &parsed.created_at, &parsed.updated_at, &parsed.cwd, &parsed.session_name,
421	                       &parsed.branch, resolved_id, parsed.name_is_explicit, parsed.tokens_used)?;
422	
423	        let checkpoint_number = checkpoint_number_from_path(meta_path).unwrap_or(0);
424	        let os_user = cwd_to_os_user(&parsed.cwd);
425	        let direct = direct_authors.get(&jsonl_path)
426	            .or_else(|| direct_authors.get(meta_path))
427	            .cloned();
428	
429	        if let (Some(u), Some(a)) = (&os_user, &direct) {
430	            os_user_authors.entry(u.clone()).or_insert_with(|| a.clone());
431	        }
432	
433	        #[derive(serde::Deserialize, Default)]
434	        struct MetadataExtra {
435	            turn_id: Option<String>,
436	            checkpoint_id: Option<String>,
437	            files_touched: Option<Vec<String>>,
438	            token_usage: Option<serde_json::Value>,
439	            initial_attribution: Option<serde_json::Value>,
440	            model: Option<String>,
441	        }
442	        let extra: MetadataExtra = serde_json::from_slice(&meta_bytes).unwrap_or_default();
443	        let files_touched_json = extra.files_touched.as_deref()
444	            .map(|v| serde_json::to_string(v).unwrap_or_default())
445	            .unwrap_or_default();
446	        let token_usage_json = extra.token_usage
447	            .map(|v| v.to_string())
448	            .unwrap_or_default();
449	        let initial_attribution_json = extra.initial_attribution
450	            .map(|v| v.to_string())
451	            .unwrap_or_default();
452	
453	        pending.push(PendingCheckpoint {
454	            session_id: parsed.session_id,
455	            checkpoint_number,
456	            jsonl_path,
457	            last_turn_ts: parsed.updated_at,
458	            os_user,
459	            direct,
460	            branch: parsed.branch,
461	            turn_id: extra.turn_id.unwrap_or_default(),
462	            checkpoint_id: extra.checkpoint_id.unwrap_or_default(),
463	            files_touched_json,
464	            token_usage_json,
465	            initial_attribution_json,
466	            model: extra.model.unwrap_or_default(),
467	        });
468	    }
469	
470	    let mut count = pending.len();
471	
472	    // Build checkpoint_id → (commit_sha, commit_message) by walking each unique
473	    // branch once. A single git-log call per branch covers all checkpoints on it.
474	    let mut cp_commit_map: HashMap<String, (String, String)> = HashMap::new();
475	    {
476	        let mut seen: std::collections::HashSet<String> = std::collections::HashSet::new();
477	        for p in &pending {
478	            if !p.branch.is_empty() && seen.insert(p.branch.clone()) {
479	                cp_commit_map.extend(build_branch_checkpoint_map(repo_dir, &p.branch));
480	            }
481	        }
482	    }
483	
484	    // Pass 2: resolve authors and persist. A merge-only session inherits
485	    // the author we learned from another session sharing its os_user.
486	    for p in pending {
487	        let author = p.direct.or_else(|| {
488	            p.os_user.as_ref().and_then(|u| os_user_authors.get(u).cloned())
489	        });
490	        let os_user_str = p.os_user.unwrap_or_default();
491	
492	        // Prefer the working-branch commit SHA; fall back to checkpoint-branch SHA.
493	        let (branch_sha, commit_message) = cp_commit_map
494	            .get(&p.checkpoint_id)
495	            .map(|(s, m)| (s.as_str(), m.as_str()))
496	            .unwrap_or(("", ""));
497	        let effective_sha = if !branch_sha.is_empty() {
498	            branch_sha
499	        } else {
500	            author.as_ref().map(|a| a.sha.as_str()).unwrap_or("")
501	        };
502	
503	        upsert_checkpoint(conn, &p.session_id,
504	                          effective_sha, author.as_ref(), &p.last_turn_ts,
505	                          &p.jsonl_path, repo_dir, &os_user_str,
506	                          commit_message, &p.turn_id, &p.checkpoint_id,
507	                          &p.files_touched_json, &p.token_usage_json,
508	                          &p.initial_attribution_json, &p.model)?;
509	    }
510	
511	    // Save commit watermark so `gossamer refresh` knows where to start next time.
512	    if let Ok(out) = Command::new("git").args(["rev-parse", BRANCH]).current_dir(repo_dir).output() {
513	        if out.status.success() {
514	            let head = String::from_utf8_lossy(&out.stdout).trim().to_string();
515	            let _ = conn.execute(
516	                "UPDATE repositories SET last_indexed_commit = ?1 WHERE directory = ?2",
517	                rusqlite::params![head, repo_dir],
518	            );
519	        }
520	    }
521	
522	    // Then sweep shadow branches for in-progress sessions that haven't been
523	    // checkpointed yet. These often advance several prompts ahead of the
524	    // checkpoint branch.
525	    count += index_shadow_branches(conn, repo_id, repo_dir, resolver)?;
526	
527	    Ok(count)
528	}
