536	        .args(["show", &format!("{}:{}", branch, path)])
537	        .current_dir(repo_dir)
538	        .output()
539	        .context("failed to run git show")?;
540	
541	    if !out.status.success() {
542	        anyhow::bail!("object not found: {}:{}", branch, path);
543	    }
