547	/// Match the in-progress session layout entireio writes to shadow branches:
548	/// `.entire/metadata/<session-uuid>/full.jsonl`. Returns the session UUID.
549	pub(crate) fn shadow_session_id(path: &str) -> Option<&str> {
550	    let rest = path.strip_prefix(".entire/metadata/")?;
551	    let (uuid, tail) = rest.split_once('/')?;
552	    if tail != "full.jsonl" {
553	        return None;
554	    }
555	    if uuid.is_empty() || uuid.contains('/') {
556	        return None;
557	    }
558	    Some(uuid)
