943	/// Find the git repo directory that contains `commit_sha`, trying `preferred`
944	/// first, then falling back to all registered gossamer repos.
945	fn resolve_repo_for_commit(commit_sha: &str, preferred: &str) -> Option<String> {
946	    use std::process::Command;
947	    let has_commit = |dir: &str| {
948	        Command::new("git").args(["cat-file", "-t", commit_sha])
949	            .current_dir(dir).output()
950	            .map(|o| o.status.success()).unwrap_or(false)
951	    };
952	    if !preferred.is_empty() && std::path::Path::new(preferred).exists() && has_commit(preferred) {
953	        return Some(preferred.to_string());
954	    }
955	    let Ok(conn) = crate::db::connect() else { return None; };
956	    let Ok(mut stmt) = conn.prepare("SELECT directory FROM repositories") else { return None; };
957	    let dirs: Vec<String> = stmt.query_map([], |r| r.get(0))
958	        .map(|rs| rs.flatten().collect()).unwrap_or_default();
959	    for dir in dirs {
960	        if has_commit(&dir) { return Some(dir); }
961	    }
962	    None
963	}
