965	/// Fetch the diff for `file` in `commit_sha`, colorised with ANSI SGR.
966	fn fetch_file_diff(commit_sha: &str, repo_dir: &str, file: &str) -> Vec<String> {
967	    use std::process::Command;
968	    let t = crate::theme::get();
969	    if commit_sha.is_empty() {
970	        return vec![format!("      \x1b[{ft}m(no commit SHA available)\x1b[0m", ft = t.text_faint)];
971	    }
972	    let Some(actual_dir) = resolve_repo_for_commit(commit_sha, repo_dir) else {
973	        return vec![format!("      \x1b[{ft}m(commit not found in any registered repo)\x1b[0m", ft = t.text_faint)];
974	    };
975	    let out = Command::new("git")
976	        .args(["show", commit_sha, "--", file])
977	        .current_dir(&actual_dir)
978	        .output();
979	    let Ok(out) = out else {
980	        return vec![format!("      \x1b[{ft}m(could not run git show)\x1b[0m", ft = t.text_faint)];
981	    };
982	    let raw = String::from_utf8_lossy(&out.stdout);
983	    let mut lines: Vec<String> = Vec::new();
984	    let mut in_hunk = false;
985	    for line in raw.lines() {
986	        if line.starts_with("@@") { in_hunk = true; }
987	        if !in_hunk { continue; }
988	        let colored = if line.starts_with('+') && !line.starts_with("+++") {
989	            format!("      \x1b[{c}m{line}\x1b[0m", c = t.fresh)
990	        } else if line.starts_with('-') && !line.starts_with("---") {
991	            format!("      \x1b[{c}m{line}\x1b[0m", c = t.error)
992	        } else if line.starts_with("@@") {
993	            format!("      \x1b[{c}m{line}\x1b[0m", c = t.label)
994	        } else {
995	            format!("      \x1b[{c}m{line}\x1b[0m", c = t.text_dim)
996	        };
997	        lines.push(colored);
998	        if lines.len() >= 300 {
999	            lines.push(format!("      \x1b[{ft}m… truncated\x1b[0m", ft = t.text_faint));
1000	            break;
1001	        }
1002	    }
1003	    if lines.is_empty() {
1004	        lines.push(format!("      \x1b[{ft}m(empty diff)\x1b[0m", ft = t.text_faint));
1005	    }
1006	    lines
1007	}
