1194	fn xml_root_tag(text: &str) -> &str {
1195	    let t = text.trim_start();
1196	    let inner = t.strip_prefix('<').unwrap_or(t);
1197	    let inner = inner.trim_start_matches(['!', '/']);
1198	    let end = inner.find(|c: char| c == '>' || c == ' ' || c == '\n').unwrap_or(inner.len());
1199	    let tag = &inner[..end];
1200	    if tag.is_empty() { "xml" } else { tag }
1201	}
