1203	fn strip_xml_tags(text: &str) -> String {
1204	    let mut out = String::new();
1205	    let mut in_tag = false;
1206	    for c in text.chars() {
1207	        match c {
1208	            '<' => { in_tag = true; }
1209	            '>' => { in_tag = false; }
1210	            '\n' if in_tag => {}
1211	            _ if !in_tag => out.push(c),
1212	            _ => {}
1213	        }
1214	    }
1215	    out
1216	}
