1218	fn wrap(text: &str, width: usize) -> Vec<String> {
1219	    if width < 4 { return text.lines().map(str::to_string).collect(); }
1220	    let mut out = Vec::new();
1221	    for raw_line in text.lines() {
1222	        if raw_line.is_empty() { out.push(String::new()); continue; }
1223	        let mut remaining = raw_line;
1224	        loop {
1225	            if remaining.chars().count() <= width {
1226	                out.push(remaining.to_string());
1227	                break;
1228	            }
1229	            let break_pos = remaining.chars().take(width)
1230	                .collect::<String>()
1231	                .rfind(' ')
1232	                .unwrap_or(width);
1233	            let byte_pos = remaining.char_indices().nth(break_pos)
1234	                .map(|(i, _)| i)
1235	                .unwrap_or(remaining.len());
1236	            out.push(remaining[..byte_pos].to_string());
1237	            remaining = remaining[byte_pos..].trim_start_matches(' ');
1238	        }
1239	    }
1240	    out
1241	}
