1243	fn rel_time(iso: &str) -> String {
1244	    let Ok(dt) = DateTime::parse_from_rfc3339(iso) else { return iso.to_string(); };
1245	    let secs = (Utc::now() - dt.with_timezone(&Utc)).num_seconds().max(0);
1246	    if secs < 604_800 {
1247	        match secs {
1248	            s if s < 60     => "just now".into(),
1249	            s if s < 3_600  => format!("{} min{} ago", s/60,     if s/60==1     {""} else {"s"}),
1250	            s if s < 86_400 => format!("{} hr{} ago",  s/3_600,  if s/3_600==1  {""} else {"s"}),
1251	            s               => format!("{} day{} ago", s/86_400, if s/86_400==1 {""} else {"s"}),
1252	        }
1253	    } else {
1254	        dt.with_timezone(&Local).format("%m/%d/%y").to_string()
1255	    }
1256	}
