1260	fn git_current_branch(cwd: &str) -> Option<String> {
1261	    let out = std::process::Command::new("git")
1262	        .args(["rev-parse", "--abbrev-ref", "HEAD"])
1263	        .current_dir(cwd)
1264	        .output()
1265	        .ok()?;
1266	    if !out.status.success() { return None; }
1267	    let s = String::from_utf8_lossy(&out.stdout).trim().to_string();
1268	    if s.is_empty() || s == "HEAD" { None } else { Some(s) }
1269	}
