1273	        .args(["rev-parse", "--show-toplevel"])
1274	        .current_dir(cwd)
1275	        .output()
1276	        .ok()?;
1277	    if !root_out.status.success() { return None; }
1278	    let repo_root = String::from_utf8_lossy(&root_out.stdout).trim().to_string();
1279	
1280	    let repo_path = std::path::Path::new(&repo_root);
1281	    let parent = repo_path.parent()?;
1282	    let repo_name = repo_path.file_name()?.to_str()?;
1283	    let wt_path = parent.join(format!("{repo_name}-{branch}"));
1284	
1285	    // Branch already exists; add a worktree pointing at it.
1286	    let _ = std::process::Command::new("git")
1287	        .args(["worktree", "add", wt_path.to_str()?, branch])
1288	        .current_dir(&repo_root)
1289	        .output();
1290	
1291	    if wt_path.exists() { Some(wt_path.to_string_lossy().to_string()) } else { None }
1292	}
