1294	fn resume_via_entire(dir: &str, branch: &str) {
1295	    use std::os::unix::process::CommandExt;
1296	
1297	    let launch_dir = if !branch.is_empty() {
1298	        let current = git_current_branch(dir);
1299	        if current.as_deref() != Some(branch) {
1300	            create_resume_worktree(dir, branch).unwrap_or_else(|| dir.to_string())
1301	        } else {
1302	            dir.to_string()
1303	        }
1304	    } else {
1305	        dir.to_string()
1306	    };
1307	
1308	    let mut entire = std::process::Command::new("entire");
1309	    entire.args(["session", "resume"]).current_dir(&launch_dir);
1310	    if !branch.is_empty() { entire.arg(branch); }
1311	
1312	    let Ok(out) = entire.output() else { eprintln!("entire session resume failed"); return; };
1313	
1314	    let cmd_str = String::from_utf8_lossy(&out.stdout).trim().to_string();
1315	    if cmd_str.is_empty() { eprintln!("entire resume returned no command"); return; }
1316	
1317	    let mut parts = cmd_str.split_whitespace();
1318	    let Some(prog) = parts.next() else { return; };
1319	    let args: Vec<&str> = parts.collect();
1320	    let err = std::process::Command::new(prog).args(&args).current_dir(&launch_dir).exec();
1321	    eprintln!("exec failed: {err}");
1322	}
