1324	/// Find a Claude session by ID. Returns `(cwd, git_branch)` from the JSONL if found,
1325	/// so `claude --resume` can be run from the correct directory and branch is known.
1326	fn find_claude_session_cwd(session_id: &str) -> Option<(String, String)> {
1327	    use std::io::BufRead;
1328	    let home = std::env::var("HOME").ok()?;
1329	    let projects = std::path::PathBuf::from(&home).join(".claude/projects");
1330	    for dir in std::fs::read_dir(&projects).ok()?.flatten() {
1331	        let jsonl = dir.path().join(format!("{session_id}.jsonl"));
1332	        if !jsonl.exists() { continue; }
1333	        let Ok(file) = std::fs::File::open(&jsonl) else { return Some((String::new(), String::new())); };
1334	        let mut cwd = String::new();
1335	        let mut branch = String::new();
1336	        for line in std::io::BufReader::new(file).lines().flatten() {
1337	            let Ok(v) = serde_json::from_str::<serde_json::Value>(&line) else { continue };
1338	            if matches!(v["type"].as_str(), Some("user") | Some("system")) {
1339	                if cwd.is_empty() {
1340	                    if let Some(c) = v["cwd"].as_str() { cwd = c.to_string(); }
1341	                }
1342	                if branch.is_empty() {
1343	                    if let Some(b) = v["gitBranch"].as_str() { branch = b.to_string(); }
1344	                }
1345	                if !cwd.is_empty() && !branch.is_empty() { break; }
1346	            }
1347	        }
1348	        return Some((cwd, branch));
1349	    }
1350	    None
1351	}
