1353	fn do_resume(_agent: &str, session_id: &str, session_branch: &str, session_cwd: &str) {
1354	    let current = git_current_branch(session_cwd);
1355	    let same_branch = !session_branch.is_empty()
1356	        && current.as_deref() == Some(session_branch);
1357	
1358	    let dir = if same_branch || session_branch.is_empty() {
1359	        session_cwd.to_string()
1360	    } else {
1361	        create_resume_worktree(session_cwd, session_branch)
1362	            .unwrap_or_else(|| session_cwd.to_string())
1363	    };
1364	
1365	    resume_session(session_id, &dir);
1366	}
