1368	/// Resume a session by ID, falling back to `entire resume` if the Claude JSONL is absent.
1369	/// `fallback_cwd` is used for `entire resume` if the Claude session isn't found.
1370	pub fn resume_session(session_id: &str, fallback_cwd: &str) {
1371	    use std::os::unix::process::CommandExt;
1372	    if let Some((session_cwd, session_branch)) = find_claude_session_cwd(session_id) {
1373	        let launch_dir = if session_cwd.is_empty() || !std::path::Path::new(&session_cwd).exists() {
1374	            fallback_cwd.to_string()
1375	        } else {
1376	            session_cwd
1377	        };
1378	        let err = std::process::Command::new("claude")
1379	            .arg("--resume")
1380	            .arg(session_id)
1381	            .current_dir(&launch_dir)
1382	            .exec();
1383	        eprintln!("exec failed: {err}");
1384	        // exec failed — fall back to entire resume, checking out the session branch first
1385	        resume_via_entire(&launch_dir, &session_branch);
1386	    } else {
1387	        resume_via_entire(fallback_cwd, "");
1388	    }
1389	}
