1477	// `Back` returns to whatever called show (the sessions list, the repo TUI, or
1478	// the CLI). `Quit` propagates a full-app exit so q from anywhere quits.
1479	enum PagerOutcome { Back, Quit, Resume, Delete, GoToSessions, GoToRepo(String) }
1480	
1481	fn pager(cards: &[Card], start_ts: Option<&str>, checkpoint_id: Option<&str>, _hit_off: Option<u64>) -> Result<PagerOutcome> {
1482	    let (term_w, term_h) = terminal::size().unwrap_or((120, 40));
1483	    let mut w = term_w as usize;
1484	    let mut h = (term_h as usize).saturating_sub(1);
1485	
1486	    let mut collapsed: std::collections::HashSet<usize> = cards.iter().enumerate()
1487	        .filter_map(|(i, c)| if matches!(c, Card::ToolRound { .. } | Card::Checkpoint(_)) { Some(i) } else { None })
1488	        .collect();
1489	
1490	    let mut expanded_files: std::collections::HashSet<(usize, usize)> = std::collections::HashSet::new();
1491	    let mut diff_cache: std::collections::HashMap<(usize, usize), Vec<String>> = std::collections::HashMap::new();
1492	
1493	    let (mut flat, mut selectables, mut starts) = build_flat(&cards, w, &collapsed, &expanded_files, &diff_cache);
1494	
1495	    let mut stdout = io::stdout();
1496	
1497	    let orig_hook = std::panic::take_hook();
1498	    std::panic::set_hook(Box::new(move |info| {
1499	        let mut out = io::stdout();
1500	        let _ = execute!(out, LeaveAlternateScreen, cursor::Show);
1501	        let _ = terminal::disable_raw_mode();
1502	        orig_hook(info);
1503	    }));
1504	
1505	    terminal::enable_raw_mode()?;
1506	    execute!(stdout, EnterAlternateScreen, cursor::Hide)?;
1507	
1508	    // Jump to the target: checkpoint_id wins, then timestamp, then start.
1509	    let initial_sel = if let Some(cpid) = checkpoint_id {
1510	        cards.iter().enumerate().find_map(|(ci, card)| {
1511	            if let Card::Checkpoint(cp) = card {
1512	                if cp.checkpoint_id == cpid {
1513	                    selectables.iter().position(|s| *s == Selectable::Card(ci))
1514	                } else { None }
1515	            } else { None }
1516	        }).unwrap_or(0)
1517	    } else {
1518	        start_ts.and_then(|ts| {
1519	            // 1. Exact string match.
1520	            let exact = cards.iter().enumerate().find_map(|(ci, card)| {
1521	                let card_ts = match card {
1522	                    Card::UserMsg { ts, .. } | Card::AsstMsg { ts, .. } | Card::System { ts, .. } => ts.as_str(),
1523	                    _ => return None,
1524	                };
1525	                if card_ts == ts {
1526	                    selectables.iter().position(|s| *s == Selectable::Card(ci))
1527	                } else { None }
1528	            });
1529	            if exact.is_some() { return exact; }
1530	
1531	            // 2. Nearest-timestamp fallback: parse as RFC 3339 and pick the card
1532	            //    closest in time to the target.  Handles merged messages (where
1533	            //    the exact timestamp was lost) and minor format differences.
1534	            use chrono::DateTime;
1535	            let target_dt = DateTime::parse_from_rfc3339(ts).ok()?;
1536	            let mut best_ci: Option<usize> = None;
1537	            let mut best_diff = i64::MAX;
1538	            for (ci, card) in cards.iter().enumerate() {
1539	                let card_ts = match card {
1540	                    Card::UserMsg { ts, .. } | Card::AsstMsg { ts, .. } | Card::System { ts, .. } => ts.as_str(),
1541	                    _ => continue,
1542	                };
1543	                if let Ok(dt) = DateTime::parse_from_rfc3339(card_ts) {
1544	                    let diff = (dt - target_dt).num_milliseconds().abs();
1545	                    if diff < best_diff {
1546	                        best_diff = diff;
1547	                        best_ci = Some(ci);
1548	                    }
1549	                }
1550	            }
1551	            // Only jump if we found something within 30 seconds to avoid landing
1552	            // on an unrelated message when the session content is very different.
1553	            best_ci.filter(|_| best_diff <= 30_000)
1554	                .and_then(|ci| selectables.iter().position(|s| *s == Selectable::Card(ci)))
1555	        }).unwrap_or(0)
1556	    };
1557	
1558	    let mut sel: usize = initial_sel;
1559	    let mut scroll: usize = 0;
1560	    let mut flash:  Option<&str> = None;
1561	    let mut awaiting_delete = false;
1562	
1563	    let result: Result<PagerOutcome> = loop {
1564	        let s = starts[sel];
1565	        let e = starts.get(sel + 1).copied().unwrap_or(flat.len());
1566	        if s < scroll          { scroll = s; }
1567	        else if e > scroll + h { scroll = e.saturating_sub(h); }
1568	
1569	        if let Err(err) = draw(&mut stdout, &flat, &starts, sel, scroll, h, w, selectables.len(), flash) {
1570	            break Err(anyhow::anyhow!(err));
1571	        }
1572	
1573	        match event::read() {
1574	            Err(e) => break Err(e.into()),
1575	            Ok(Event::Key(k)) => {
1576	                let prev_flash = flash.take();
1577	                match (k.code, k.modifiers) {
1578	                    (KeyCode::Char('q'), _) => break Ok(PagerOutcome::Quit),
1579	                    (KeyCode::Char('c'), KeyModifiers::CONTROL) => break Ok(PagerOutcome::Quit),
1580	                    (KeyCode::Esc | KeyCode::Left, _) => break Ok(PagerOutcome::Back),
1581	                    (KeyCode::Char('r'), _) => break Ok(PagerOutcome::Resume),
1582	                    (KeyCode::Char('d'), _) => {
1583	                        awaiting_delete = true;
1584	                        flash = Some("  Delete session? Press y to confirm, any other key to cancel  ");
1585	                        continue;
1586	                    }
1587	                    (KeyCode::Char('y'), _) if awaiting_delete => {
1588	                        break Ok(PagerOutcome::Delete);
1589	                    }
1590	
1591	                    (KeyCode::Down | KeyCode::Char('j'), _) => {
1592	                        if sel + 1 < selectables.len() { sel += 1; }
1593	                    }
1594	                    (KeyCode::Up | KeyCode::Char('k'), _) => {
1595	                        if sel > 0 { sel -= 1; }
1596	                    }
1597	                    (KeyCode::Char('g'), _) => { sel = 0; }
1598	                    (KeyCode::Char('G'), _) => { sel = selectables.len().saturating_sub(1); }
1599	
1600	                    (KeyCode::Char(']'), _) => {
1601	                        let is_cp = |s: &Selectable| match s {
1602	                            Selectable::Card(ci) => matches!(&cards[*ci], Card::Checkpoint(_)),
1603	                            Selectable::CheckpointHeader(..) => true,
1604	                            _ => false,
1605	                        };
1606	                        if let Some(i) = selectables.iter().enumerate().skip(sel + 1).find(|(_, s)| is_cp(s)).map(|(i, _)| i) {
1607	                            sel = i;
1608	                        }
1609	                    }
1610	                    (KeyCode::Char('['), _) => {
1611	                        let is_cp = |s: &Selectable| match s {
1612	                            Selectable::Card(ci) => matches!(&cards[*ci], Card::Checkpoint(_)),
1613	                            Selectable::CheckpointHeader(..) => true,
1614	                            _ => false,
1615	                        };
1616	                        if let Some(i) = selectables.iter().enumerate().take(sel).rfind(|(_, s)| is_cp(s)).map(|(i, _)| i) {
1617	                            sel = i;
1618	                        }
1619	                    }
1620	
1621	                    (KeyCode::Char('u'), _) | (KeyCode::PageUp, _) => {
1622	                        scroll = scroll.saturating_sub(h / 2);
1623	                        sel = flat[scroll].0;
1624	                    }
1625	                    (KeyCode::PageDown, _) => {
1626	                        scroll = (scroll + h / 2).min(flat.len().saturating_sub(h));
1627	                        sel = flat[scroll].0;
1628	                    }
1629	
1630	                    (KeyCode::Char('y'), _) | (KeyCode::Char('c'), _) => {
1631	                        let text = match &selectables[sel] {
1632	                            Selectable::Card(ci)             => card_text(&cards[*ci]),
1633	                            Selectable::ToolHeader(ci)       => card_text(&cards[*ci]),
1634	                            Selectable::CheckpointHeader(ci) => card_text(&cards[*ci]),
1635	                            Selectable::ToolCall(ci, ti) => {
1636	                                if let Card::ToolRound { parts } = &cards[*ci] {
1637	                                    parts.get(*ti).map_or(String::new(), tool_call_text)
1638	                                } else { String::new() }
1639	                            }
1640	                            Selectable::CheckpointFile(ci, fi) => {
1641	                                if let Card::Checkpoint(cp) = &cards[*ci] {
1642	                                    cp.files_touched.get(*fi).cloned().unwrap_or_default()
1643	                                } else { String::new() }
1644	                            }
1645	                        };
1646	                        copy_to_clipboard(&text);
1647	                        flash = Some("  ✓ copied to clipboard  ");
1648	                    }
1649	
1650	                    // Space/Right/Enter: expand ToolRound/Checkpoint, collapse via header, or navigate
1651	                    (KeyCode::Char(' ') | KeyCode::Right | KeyCode::Enter, _) => {
1652	                        let expand_action = match &selectables[sel] {
1653	                            Selectable::Card(ci) if matches!(&cards[*ci], Card::ToolRound { .. }) => {
1654	                                Some((true, *ci, false))
1655	                            }
1656	                            Selectable::Card(ci) if matches!(&cards[*ci], Card::Checkpoint(_)) => {
1657	                                Some((true, *ci, true))
1658	                            }
1659	                            Selectable::ToolHeader(ci) => Some((false, *ci, false)),
1660	                            Selectable::CheckpointHeader(ci) => Some((false, *ci, true)),
1661	                            _ => None,
1662	                        };
1663	                        if let Some((expand, card_idx, is_checkpoint)) = expand_action {
1664	                            if expand { collapsed.remove(&card_idx); } else { collapsed.insert(card_idx); }
1665	                            let (nf, ns, nst) = build_flat(cards, w, &collapsed, &expanded_files, &diff_cache);
1666	                            flat   = nf;
1667	                            starts = nst;
1668	                            sel = if expand {
1669	                                if is_checkpoint {
1670	                                    ns.iter().position(|s| *s == Selectable::CheckpointHeader(card_idx))
1671	                                } else {
1672	                                    ns.iter().position(|s| *s == Selectable::ToolHeader(card_idx))
1673	                                }
1674	                            } else {
1675	                                ns.iter().position(|s| *s == Selectable::Card(card_idx))
1676	                            }.unwrap_or_else(|| sel.min(ns.len().saturating_sub(1)));
1677	                            selectables = ns;
1678	                        } else if let Selectable::CheckpointFile(ci, fi) = &selectables[sel] {
1679	                            let key = (*ci, *fi);
1680	                            if expanded_files.contains(&key) {
1681	                                expanded_files.remove(&key);
1682	                            } else {
1683	                                if !diff_cache.contains_key(&key) {
1684	                                    if let Card::Checkpoint(cp) = &cards[*ci] {
1685	                                        if let Some(f) = cp.files_touched.get(*fi) {
1686	                                            diff_cache.insert(key, fetch_file_diff(&cp.commit_sha, &cp.repo_dir, f));
1687	                                        }
1688	                                    }
1689	                                }
1690	                                expanded_files.insert(key);
1691	                            }
1692	                            let target = Selectable::CheckpointFile(*ci, *fi);
1693	                            let (nf, ns, nst) = build_flat(cards, w, &collapsed, &expanded_files, &diff_cache);
1694	                            flat = nf; starts = nst;
1695	                            sel = ns.iter().position(|s| *s == target)
1696	                                .unwrap_or_else(|| sel.min(ns.len().saturating_sub(1)));
1697	                            selectables = ns;
1698	                        } else if let Selectable::Card(ci) = &selectables[sel] {
1699	                            match &cards[*ci] {
1700	                                Card::RepoLink { dir, .. } => {
1701	                                    break Ok(PagerOutcome::GoToRepo(dir.clone()));
1702	                                }
1703	                                Card::Header { .. } => {
1704	                                    break Ok(PagerOutcome::GoToSessions);
1705	                                }
1706	                                _ => { flash = prev_flash; }
1707	                            }
1708	                        } else {
1709	                            flash = prev_flash;
1710	                        }
1711	                    }
1712	
1713	                    (KeyCode::Char('/'), _) => {
1714	                        if let Some(query) = super::collect_search_query(&mut stdout, w, h) {
1715	                            if !query.trim().is_empty() {
1716	                                execute!(stdout, LeaveAlternateScreen, cursor::Show)?;
1717	                                terminal::disable_raw_mode()?;
1718	                                super::search::run(&query, 10, false).unwrap_or(false);
1719	                                terminal::enable_raw_mode()?;
1720	                                execute!(stdout, EnterAlternateScreen, cursor::Hide)?;
1721	                                execute!(stdout, terminal::Clear(ClearType::All))?;
1722	                            }
1723	                        }
1724	                    }
1725	
1726	                    _ => { awaiting_delete = false; flash = prev_flash; }
1727	                }
1728	            }
1729	            Ok(Event::Resize(new_w, new_h)) => {
1730	                w = new_w as usize;
1731	                h = (new_h as usize).saturating_sub(1);
1732	                let (nf, ns, nst) = build_flat(&cards, w, &collapsed, &expanded_files, &diff_cache);
1733	                flat = nf; selectables = ns; starts = nst;
1734	                execute!(stdout, terminal::Clear(ClearType::All)).ok();
1735	            }
1736	            Ok(_) => {}
1737	        }
1738	    };
1739	
1740	    execute!(stdout, LeaveAlternateScreen, cursor::Show)?;
1741	    terminal::disable_raw_mode()?;
1742	    result
1743	}
1744	
1745	fn draw(
1746	    stdout: &mut impl Write,
1747	    flat:   &[(usize, String)],
1748	    starts: &[usize],
1749	    sel:    usize,
1750	    scroll: usize,
1751	    h:      usize,
1752	    w:      usize,
1753	    total:  usize,
1754	    flash:  Option<&str>,
1755	) -> io::Result<()> {
1756	    use crossterm::queue;
1757	    let accent = crate::theme::get().accent;
1758	
1759	    let end = (scroll + h).min(flat.len());
1760	
1761	    // Build the entire frame into one buffer; flush once to eliminate flicker.
1762	    // Use explicit cursor::MoveTo per row so embedded newlines in content can't
1763	    // shift subsequent rows into the wrong position.
1764	    let mut buf: Vec<u8> = Vec::with_capacity((w + 40) * (h + 2));
1765	
1766	    for row in 0..h {
1767	        queue!(buf, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
1768	
1769	        let flat_idx = scroll + row;
1770	        if flat_idx < end {
1771	            let (card_idx, line) = &flat[flat_idx];
1772	            if *card_idx == sel {
1773	                let is_first = flat_idx == 0 || flat[flat_idx - 1].0 != sel;
1774	                if is_first {
1775	                    let t = crate::theme::get();
1776	                    let bg = t.sel_bg;
1777	                    let colored = super::with_bg(line, bg);
1778	                    let pad = w.saturating_sub(2 + super::visible_width(line));
1779	                    write!(buf, "\x1b[{bg}m  {colored}{}\x1b[0m", " ".repeat(pad))?;
1780	                } else {
1781	                    write!(buf, "\x1b[{}m▌\x1b[0m {line}", accent)?;
1782	                }
1783	            } else {
1784	                write!(buf, "  ")?;
1785	                buf.extend_from_slice(line.as_bytes());
1786	            }
1787	        }
1788	    }
1789	
1790	    // Status bar
1791	    let sel_end = starts.get(sel + 1).copied().unwrap_or(flat.len());
1792	    let base = format!(
1793	        "  {}/{} msgs  lines {}-{}  j/k ↑↓ navigate  ]/[ checkpoint  u/PgDn page  g/G ends  y/c copy  r resume  d delete  / search  q quit  ",
1794	        sel + 1, total, starts[sel] + 1, sel_end,
1795	    );
1796	    let bar = if let Some(msg) = flash {
1797	        let skip = msg.chars().count();
1798	        let rest: String = base.chars().skip(skip).collect();
1799	        format!("{msg}{rest}")
1800	    } else {
1801	        base
1802	    };
1803	    let bar_display: String = bar.chars().take(w).collect();
1804	    let padded = format!("{bar_display:width$}", width = w);
1805	    queue!(buf, cursor::MoveTo(0, h as u16))?;
1806	    write!(buf, "\x1b[7m{padded}\x1b[0m")?;
1807	
1808	    stdout.write_all(&buf)?;
1809	    stdout.flush()
1810	}
